fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    
    // Iterate through all parent nodes (indices 0 to floor(n/2) - 1)
    for i in 0..n / 2 {
        let left_child = 2 * i + 1;
        let right_child = 2 * i + 2;
        
        // Check left child (always exists if we're in parent range)
        if left_child < n && a[left_child] < a[i] {
            return false;
        }
        
        // Check right child (may not exist)
        if right_child < n && a[right_child] < a[i] {
            return false;
        }
    }
    
    true
}